const parityMismatches = [];
lanes.forEach((lane) => {
  if (!lane.promise) parityMismatches.push(`${lane.name}: missing promise`);
  if (!lane.validateLive) parityMismatches.push(`${lane.name}: missing live validation copy`);
  if (!lane.storyline) parityMismatches.push(`${lane.name}: missing storyline`);
  if (!Array.isArray(lane.moves) || lane.moves.length !== 3) parityMismatches.push(`${lane.name}: expected three moves`);
  if (!Array.isArray(lane.modules) || !lane.modules.length) parityMismatches.push(`${lane.name}: missing module chips`);
  if (!Array.isArray(lane.signals) || lane.signals.length < 5) parityMismatches.push(`${lane.name}: expected at least five signals`);
});
assertRule(results, 'authorized_lane_parity_inputs_complete', parityMismatches.length === 0, parityMismatches.join('; '));

