assertRule(results, 'w198_trace_and_production_prompt_ready', w198ImportCompletedRunnerResultAndTargetedLinkTestTrace.traceSamples.some((item) => item.event === 'w198_w197_completed_runner_result_imported') && w198ImportCompletedRunnerResultAndTargetedLinkTestTrace.traceSamples.some((item) => item.event === 'w198_targeted_visual_evidence_boundary') && w198ImportCompletedRunnerResultAndTargetedLinkTest.productionReadinessNextPrompt.block === 'W199: Authenticated Five-Link Landing Evidence Review And Production Readiness Gate', JSON.stringify(w198ImportCompletedRunnerResultAndTargetedLinkTestTrace.traceSamples));
assertRule(results, 'w199_harness_and_report_ready', w199AuthenticatedFiveLinkLandingEvidenceReview.schema === 'idb.w199-authenticated-five-link-landing-evidence-review.v1' && w199AuthenticatedFiveLinkLandingEvidenceReview.status === 'BLOCKED_W199_AUTHENTICATED_LINK_EVIDENCE_REQUIRED' && /"harness:authenticated-five-link-landing-evidence-review-w199": "node tools\/run_authenticated_five_link_landing_evidence_review_w199_harness\.js"/.test(read(files.packageJson)) && /W199 Authenticated Five-Link Landing Evidence Review/.test(read(generatedFiles.w199AuthenticatedFiveLinkLandingEvidenceReview)), w199AuthenticatedFiveLinkLandingEvidenceReview.schema);
assertRule(results, 'w199_evidence_review_blocks_without_screenshots', w199AuthenticatedFiveLinkLandingEvidenceReview.evidenceReview.w198ImportReady === true && w199AuthenticatedFiveLinkLandingEvidenceReview.evidenceReview.authenticatedEvidenceProvided === false && w199AuthenticatedFiveLinkLandingEvidenceReview.evidenceReview.allFiveRecordLandingsPassed === false && w199AuthenticatedFiveLinkLandingEvidenceReview.productionReadinessDecision.productionReady === false, JSON.stringify(w199AuthenticatedFiveLinkLandingEvidenceReview.evidenceReview));
assertRule(results, 'w199_pass_fail_table_covers_five_roles', w199AuthenticatedFiveLinkLandingEvidenceReview.passFailTable.length === 5 && ['customer', 'sales_order', 'hero_item', 'matrix_or_proof_item', 'component_item'].every((role) => w199AuthenticatedFiveLinkLandingEvidenceReview.passFailTable.some((row) => row.role === role && row.result === 'blocked_missing_or_failed_authenticated_landing_evidence')), JSON.stringify(w199AuthenticatedFiveLinkLandingEvidenceReview.passFailTable));
