assertRule(results, 'w199_trace_and_next_prompt_ready', w199AuthenticatedFiveLinkLandingEvidenceReviewTrace.traceSamples.some((item) => item.event === 'w199_authenticated_landing_evidence_review') && w199AuthenticatedFiveLinkLandingEvidenceReviewTrace.traceSamples.some((item) => item.event === 'w199_production_readiness_decision') && w199AuthenticatedFiveLinkLandingEvidenceReview.nextPrompt.block === 'W199R: Authenticated Five-Link Screenshot Intake Retest', JSON.stringify(w199AuthenticatedFiveLinkLandingEvidenceReviewTrace.traceSamples));
assertRule(results, 'w2_plan_duplicate_next_action_removed', !/Enter the prospect, website, and conversation notes\. IDB resolves the industry family, builds the packet, and moves you to Review\./.test(userscript) && /function renderPlanView/.test(userscript) && /renderDemoSetup/.test(userscript), '');
assertRule(results, 'h8_trace_sample_present', fs.existsSync(generatedFiles.h8ReleaseCandidateTraceSample) && JSON.parse(read(generatedFiles.h8ReleaseCandidateTraceSample)).dryRunObjectPacket.creationAllowed === false && /roiCompetitiveReview/.test(read(generatedFiles.h8ReleaseCandidateTraceSample)), generatedFiles.h8ReleaseCandidateTraceSample);
assertRule(results, 'georgetown_trace_review_present', fs.existsSync(traceReview) && /PASS for lane-selection behavior/.test(read(traceReview)), traceReview);
assertRule(results, 'georgetown_dry_run_report_present', fs.existsSync(generatedFiles.georgetownDryRunReport) && /GO for review-only packet/.test(read(generatedFiles.georgetownDryRunReport)), generatedFiles.georgetownDryRunReport);
assertRule(results, 'georgetown_dry_run_packet_present', fs.existsSync(generatedFiles.georgetownDryRunPacket) && JSON.parse(read(generatedFiles.georgetownDryRunPacket)).creationAllowed === false, generatedFiles.georgetownDryRunPacket);

const forbiddenUiTerms = [
  'growth gap',
  'certification',
  'certified',
  'Run Demo Reset',
  'Open Old Design',
  'Regression Comparison'
];
const visibleText = `${userscript}\n${read(files.readme)}\n${read(files.preview)}`;
forbiddenUiTerms.forEach((term) => {
  assertRule(results, `forbidden_term_absent:${term}`, !visibleText.toLowerCase().includes(term.toLowerCase()), term);
});

const failures = results.filter((result) => !result.pass);
const report = [
  '# Intelligent Demo Builder Drawer Validation',
  '',
  `Generated: ${new Date().toISOString()}`,
  '',
  `Decision: ${failures.length ? 'FAIL' : 'PASS'}`,
  '',
  '| Status | Rule | Detail |',
  '| --- | --- | --- |',
  ...results.map((result) => `| ${result.pass ? 'PASS' : 'FAIL'} | ${result.name} | ${String(result.detail || '').replace(/\|/g, '/')} |`)
].join('\n');

fs.writeFileSync(path.join(root, 'validation_report.md'), `${report}\n`);

console.log(`Intelligent Demo Builder Drawer validation: ${failures.length ? 'FAIL' : 'PASS'}`);
console.log(`Checks: ${results.length - failures.length}/${results.length}`);
console.log(`Report: ${path.join(root, 'validation_report.md')}`);

if (failures.length) {
  failures.forEach((failure) => console.error(`FAIL ${failure.name}: ${failure.detail}`));
  process.exit(1);
}
